import { EMPEROR_UI, MU, HUO, SHUI, TU, JIN, EMPEROR } from '../constants/wuxingColors';

// ── 版本配色 ──
const VERSION_STYLE: Record<LineVersion, { color: string; bg: string; border: string; icon: string; desc: string }> = {
