                      {([
                        ['2月總業績', `$${trend.febRevenue.toLocaleString()}`, SHUI],
                        ['3月累積', `$${trend.marRevenue.toLocaleString()}`, MU],
                        ['2月日均', `$${trend.febDailyAvg.toLocaleString()}`, TU],
