/**
 * useDispatchReport — 派單報表資料主 hook
 *
 * 唯一資料來源：fetchLatestStructuredReport()
 * 狀態：loading → success(data) | success(empty) | error
 * 10 秒 poll version，有變化才整包重刷
 */
import { useState, useEffect, useRef, useCallback } from 'react';
import type { DispatchReportPayload } from '../types/dispatchReport';
import { fetchLatestStructuredReport, fetchStructuredReport } from '../services/dispatchReportApi';

export type ReportState =
  | { status: 'loading' }
  | { status: 'success'; data: DispatchReportPayload }
  | { status: 'empty' }
  | { status: 'error'; message: string };

export interface UseDispatchReportReturn {
  state:    ReportState;
  refetch:  () => Promise<void>;
  lastFetchedAt: string | null;
}

const POLL_MS = 10_000;

export function useDispatchReport(): UseDispatchReportReturn {
  const [state, setState]       = useState<ReportState>({ status: 'loading' });
  const [lastFetchedAt, setLast] = useState<string | null>(null);
  const lastDate = useRef<string | null>(null);

  const fetchFull = useCallback(async () => {
    setState({ status: 'loading' });
    const result = await fetchLatestStructuredReport();
    if (result.ok) {
      lastDate.current = result.data.reportMeta.date;
      setState({ status: 'success', data: result.data });
    } else if (result.errorCode === 'NO_RANKING' || result.errorCode === 'NOT_GENERATED') {
      setState({ status: 'empty' });
    } else {
      setState({ status: 'error', message: result.message });
    }
    setLast(new Date().toISOString());
  }, []);

  // Version poll — only re-fetch if date changed
  const pollVersion = useCallback(async () => {
    if (!lastDate.current) return;
    try {
      const res  = await fetch('/api/v1/latest/version');
      const json = await res.json();
      const newDate: string | undefined = json.data?.reportDate ?? json.data?.report_date;
      if (newDate && newDate !== lastDate.current) {
        const result = await fetchStructuredReport(newDate);
        if (result.ok) {
          lastDate.current = newDate;
          setState({ status: 'success', data: result.data });
          setLast(new Date().toISOString());
        }
      }
    } catch { /* silent */ }
  }, []);

  useEffect(() => {
    fetchFull();
    const t = setInterval(pollVersion, POLL_MS);
    return () => clearInterval(t);
  }, [fetchFull, pollVersion]);

  return { state, refetch: fetchFull, lastFetchedAt };
}

import { useState, useEffect, useCallback } from 'react';

export type ConnectionStatus = 'connected' | 'reconnecting' | 'disconnected';

interface HeartbeatState {
  status: ConnectionStatus;
  latency: number;
  attempts: number;
  lastCheck: Date | null;
}

export const useHeartbeat = (intervalMs = 8000) => {
  const [state, setState] = useState<HeartbeatState>(({
    status: 'connected',
    latency: -1,
    attempts: 0,
    lastCheck: null,
  }));

  const checkHealth = useCallback(async () => {
    const startTime = performance.now();
    try {
      const controller = new AbortController();
      const id = setTimeout(() => controller.abort(), 4000); // 4秒超時

      const res = await fetch('/api/v1/health', { signal: controller.signal });
      clearTimeout(id);

      const endTime = performance.now();
      const latency = Math.round(endTime - startTime);

      if (res.ok) {
        setState({
          status: 'connected',
          latency,
          attempts: 0,
          lastCheck: new Date(),
        });
      } else {
        throw new Error(`HTTP ${res.status}`);
      }
    } catch (err) {
      setState(prev => {
        const nextAttempts = prev.attempts + 1;
        // 連續三次失敗判定為斷線，否則為重連中
        const nextStatus = nextAttempts >= 3 ? 'disconnected' : 'reconnecting';
        return {
          status: nextStatus,
          latency: -1,
          attempts: nextAttempts,
          lastCheck: new Date(),
        };
      });
    }
  }, []);

  useEffect(() => {
    // 立即檢查一次
    checkHealth();

    // 建立定時器
    const timer = setInterval(() => {
      checkHealth();
    }, intervalMs);

    // 斷線時加快嘗試頻率 (指數退避或加速)
    let reconnectTimer: any;
    if (state.status !== 'connected') {
      reconnectTimer = setInterval(() => {
        checkHealth();
      }, 3000); // 斷線時每 3 秒重連
    }

    return () => {
      clearInterval(timer);
      if (reconnectTimer) clearInterval(reconnectTimer);
    };
  }, [checkHealth, intervalMs, state.status]);

  return {
    ...state,
    triggerManualCheck: checkHealth,
  };
};

import { useState, useEffect, useCallback } from 'react';

export interface ModuleInfo {
  key: string;
  label: string;
  enabled: boolean;
  locked: boolean;
  description: string;
}

export interface SystemStatusData {
  engine: {
    running: boolean;
    startedAt: string | null;
    currentTime: string;
    timezone: string;
  };
  modules: ModuleInfo[];
  storage: {
    todayDir: boolean;
    latestFile: boolean;
    logFile: boolean;
    logSize: number;
    backupCount: number;
  };
  database: {
    todayReportCount: number;
    latestSnapshot: {
      version: string;
      reportDate: string;
      auditResult: string;
      computedAt: string;
    } | null;
  };
  alerts: string[];
}

export function useSystemStatus(pollInterval = 5000) {
  const [status, setStatus] = useState<SystemStatusData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchStatus = useCallback(async () => {
    try {
      const res = await fetch('/api/v1/system/status');
      const json = await res.json();
      if (json.success) {
        setStatus(json.data);
        setError(null);
      } else {
        setError(json.message ?? '查詢失敗');
      }
    } catch (e: any) {
      setError('無法連線後端');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchStatus();
    const timer = setInterval(fetchStatus, pollInterval);
    return () => clearInterval(timer);
  }, [fetchStatus, pollInterval]);

  const boot = async () => {
    const res = await fetch('/api/v1/system/boot', { method: 'POST' });
    const json = await res.json();
    await fetchStatus();
    return json;
  };

  const stop = async () => {
    const res = await fetch('/api/v1/system/stop', { method: 'POST' });
    const json = await res.json();
    await fetchStatus();
    return json;
  };

  const repair = async () => {
    const res = await fetch('/api/v1/system/repair', { method: 'POST' });
    const json = await res.json();
    await fetchStatus();
    return json;
  };

  const toggleModule = async (moduleKey: string) => {
    const res = await fetch(`/api/v1/system/modules/${moduleKey}/toggle`, { method: 'POST' });
    const json = await res.json();
    await fetchStatus();
    return json;
  };

  return { status, loading, error, fetchStatus, boot, stop, repair, toggleModule };
}

