            <div>
              <label style={fieldLabel}>
                <span style={{ color: form.noteText ? SHUI.bright : EMPEROR_UI.textDim, fontSize: 13 }}>{form.noteText ? '✓' : '○'}</span>
                <span style={{ color: EMPEROR_UI.textMuted }}>備註</span>
