import React, { useState, useEffect, useRef, useMemo } from 'react';
import './HealingCashFlowPage.css';

interface Role {
  id: number;
  名稱: string;
  說明: string;
  主題: string;
}

const defaultPageConfig = {
  網站標題: "兆櫃AI派單系統 療癒金流四層空間",
  網站副標題: "這不是影片腳本，而是可直接開工的網頁工程版本。整體以黑框立體舞台、四層空間、3D 景深、紅包金流互動為核心。",
  主角編號: 1,
  標籤: ["網頁工程", "四層空間", "3D立體景深", "禁止英文顯示", "紅包金流互動"],
  角色資料: [
    { id: 1, 名稱: "黃金火焰", 說明: "資源金錢", 主題: "金" },
    { id: 2, 名稱: "白色高密度火焰", 說明: "穩定方法", 主題: "白" },
    { id: 3, 名稱: "帝王綠火焰", 說明: "長期權威", 主題: "綠" },
    { id: 4, 名稱: "黑鑽能量火焰", 說明: "翻身突破", 主題: "暗" },
    { id: 5, 名稱: "血紅能量火焰", 說明: "機會爆發", 主題: "紅" }
  ]
};

const positionClasses = ["中間位", "左上位", "右上位", "左下位", "右下位"];

export function HealingCashFlowPage() {
  const [pageConfig, setPageConfig] = useState(defaultPageConfig);
  const [mainId, setMainId] = useState(1);
  const [isErupting, setIsErupting] = useState(false);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const effectLayerRef = useRef<HTMLDivElement>(null);
  const flowLayerRef = useRef<HTMLDivElement>(null);

  // 排序角色：第一位為主角，其餘為配角
  const sortedRoles = useMemo(() => {
    const main = pageConfig.角色資料.find(r => r.id === mainId) || pageConfig.角色資料[0];
    const others = pageConfig.角色資料.filter(r => r.id !== mainId);
    return [main, ...others];
  }, [mainId, pageConfig.角色資料]);

  useEffect(() => {
    fetch('/api/頁面設定')
      .then(res => res.json())
      .then(res => {
        if (res.成功) {
          setPageConfig(res.資料);
          setMainId(res.資料.主角編號);
        }
      })
      .catch(err => console.warn('無法讀取設定 API，維持默認數值：', err));
  }, []);

  useEffect(() => {
    // 3D 輕量舞台傾斜
    const stage = containerRef.current;
    if (!stage) return;

    const handleMouseMove = (e: MouseEvent) => {
      const box = stage.getBoundingClientRect();
      const x = (e.clientX - box.left) / box.width;
      const y = (e.clientY - box.top) / box.height;
      const tiltY = (x - 0.5) * 4;
      const tiltX = (0.5 - y) * 3;
      stage.style.setProperty('--舞台傾斜Y', `${tiltY}deg`);
      stage.style.setProperty('--舞台傾斜X', `${tiltX}deg`);
    };

    const handleMouseLeave = () => {
      stage.style.setProperty('--舞台傾斜Y', '0deg');
      stage.style.setProperty('--舞台傾斜X', '0deg');
    };

    stage.addEventListener('mousemove', handleMouseMove);
    stage.addEventListener('mouseleave', handleMouseLeave);

    return () => {
      stage.removeEventListener('mousemove', handleMouseMove);
      stage.removeEventListener('mouseleave', handleMouseLeave);
    };
  }, []);

  function ensureAudio() {
    if (!audioCtxRef.current) {
      audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (audioCtxRef.current.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  }

  function playCoinSound(volume = 0.045, duration = 0.12, offset = 0) {
    const ctx = audioCtxRef.current;
    if (!ctx) return;
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = 'sine';
    osc.frequency.setValueAtTime(920, now);
    osc.frequency.exponentialRampToValueAtTime(1450 + offset, now + duration);

    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(volume, now + 0.01);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);

    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(now);
    osc.stop(now + duration + 0.02);
  }

  function playPaperSound(volume = 0.018, duration = 0.22) {
    const ctx = audioCtxRef.current;
    if (!ctx) return;
    const sampleRate = ctx.sampleRate;
    const bufSize = Math.floor(sampleRate * duration);
    const buf = ctx.createBuffer(1, bufSize, sampleRate);
    const output = buf.getChannelData(0);

    for (let i = 0; i < bufSize; i++) {
       output[i] = (Math.random() * 2 - 1) * (1 - i / bufSize);
    }

    const source = ctx.createBufferSource();
    const filter = ctx.createBiquadFilter();
    const gain = ctx.createGain();

    filter.type = "bandpass";
    filter.frequency.value = 1800;
    filter.Q.value = 0.8;

    gain.gain.value = volume;
    source.buffer = buf;
    source.connect(filter);
    filter.connect(gain);
    gain.connect(ctx.destination);

    source.start();
  }

  function createGlow(x: number, y: number) {
    if (!effectLayerRef.current) return;
    const glow = document.createElement("div");
    glow.className = "柔光閃爍";
    glow.style.setProperty("--光X", `${x}%`);
    glow.style.setProperty("--光Y", `${y}%`);
    effectLayerRef.current.appendChild(glow);
    setTimeout(() => glow.remove(), 650);
  }

  function getRedEnvelopeCenter() {
    const btn = document.getElementById("紅包按鈕");
    const flow = flowLayerRef.current;
    if (!btn || !flow) return { x: window.innerWidth / 2, y: 300 };
    const btnBox = btn.getBoundingClientRect();
    const flowBox = flow.getBoundingClientRect();
    return {
      x: btnBox.left + btnBox.width / 2 - flowBox.left,
      y: btnBox.top + btnBox.height / 2 - flowBox.top
    };
  }

  function spawnCoin(origin: { x: number, y: number }, step: number) {
    if (!flowLayerRef.current) return;
    const el = document.createElement("div");
    el.className = "金幣 飛出動畫 金幣旋轉";

    const dx = (Math.random() * 560 - 280) + (step * 12);
    const dy = (Math.random() * -260) + 60;
    const dz = `${140 + Math.random() * 260}px`;
    const angle = `${Math.random() * 560 - 280}deg`;

    el.style.setProperty("--起點X", `${origin.x}px`);
    el.style.setProperty("--起點Y", `${origin.y}px`);
    el.style.setProperty("--位移X", `${dx}px`);
    el.style.setProperty("--位移Y", `${dy}px`);
    el.style.setProperty("--位移Z", dz);
    el.style.setProperty("--旋轉角度", angle);
    el.style.setProperty("--持續時間", `${1.15 + Math.random() * 0.75}s`);
    el.style.setProperty("--結尾比例", `${0.88 + Math.random() * 0.48}`);

    flowLayerRef.current.appendChild(el);
    setTimeout(() => el.remove(), 2200);
  }

  function spawnPaper(origin: { x: number, y: number }, step: number) {
    if (!flowLayerRef.current) return;
    const el = document.createElement("div");
    el.className = "鈔票 飛出動畫";

    const dx = (Math.random() * 620 - 310) + (step * 10);
    const dy = (Math.random() * -220) + 90;
    const dz = `${160 + Math.random() * 220}px`;
    const angle = `${Math.random() * 220 - 110}deg`;

    el.style.setProperty("--起點X", `${origin.x}px`);
    el.style.setProperty("--起點Y", `${origin.y}px`);
    el.style.setProperty("--位移X", `${dx}px`);
    el.style.setProperty("--位移Y", `${dy}px`);
    el.style.setProperty("--位移Z", dz);
    el.style.setProperty("--旋轉角度", angle);
    el.style.setProperty("--持續時間", `${1.3 + Math.random() * 0.55}s`);
    el.style.setProperty("--結尾比例", `${0.9 + Math.random() * 0.30}`);

    flowLayerRef.current.appendChild(el);
    setTimeout(() => el.remove(), 2200);
  }

  function sparkWave(origin: { x: number, y: number }, coins: number, papers: number, step: number) {
    for (let i = 0; i < coins; i++) {
      setTimeout(() => spawnCoin(origin, step), i * 35);
    }
    for (let i = 0; i < papers; i++) {
      setTimeout(() => spawnPaper(origin, step), i * 45);
    }
  }

  function activateEruption() {
    if (isErupting) return;
    setIsErupting(true);
    ensureAudio();

    const origin = getRedEnvelopeCenter();

    createGlow(50, 58);

    // 第一波
    setTimeout(() => {
      sparkWave(origin, 14, 0, 1);
      playCoinSound(0.05, 0.12, 0);
      setTimeout(() => playCoinSound(0.042, 0.10, 50), 90);
      setTimeout(() => playCoinSound(0.04, 0.09, -40), 180);
    }, 0);

    // 第二波
    setTimeout(() => {
      sparkWave(origin, 8, 7, 2);
      playPaperSound(0.018, 0.24);
      setTimeout(() => playCoinSound(0.038, 0.09, 80), 120);
    }, 420);

    // 第三波
    setTimeout(() => {
      sparkWave(origin, 18, 10, 3);
      playPaperSound(0.02, 0.28);
      playCoinSound(0.05, 0.12, -20);
      setTimeout(() => playCoinSound(0.04, 0.11, 100), 80);
      setTimeout(() => playCoinSound(0.035, 0.10, -90), 160);
    }, 920);

    // 第四波
    setTimeout(() => {
      sparkWave(origin, 22, 12, 4);
      createGlow(50, 56);
      playCoinSound(0.055, 0.14, 0);
      setTimeout(() => playPaperSound(0.02, 0.22), 90);
      setTimeout(() => playCoinSound(0.038, 0.11, 60), 140);
      setTimeout(() => playCoinSound(0.03, 0.09, -60), 250);
    }, 1480);

    setTimeout(() => {
      setIsErupting(false);
    }, 2600);
  }

  function getThemeClass(theme: string) {
    if (theme === "金") return "金主題";
    if (theme === "白") return "白主題";
    if (theme === "綠") return "綠主題";
    if (theme === "暗") return "暗主題";
    return "紅主題";
  }

  return (
    <>
      <div className="healing-page-bg" />
      <div className="外層空間" />

      <div className="頁面">
        <div className="頁首">
          <div className="標題區">
            <div className="標籤列">
              {pageConfig.標籤.map((tag: string, idx: number) => (
                <div key={idx} className="標籤">{tag}</div>
              ))}
            </div>
            <h1>{pageConfig.網站標題}</h1>
            <p className="副標題">{pageConfig.網站副標題}</p>
          </div>

          <aside className="規格卡">
            <h2>工程固定規則</h2>
            <div className="mt-2 space-y-1">
               <label className="block text-sm">切換主角：</label>
               <select 
                 className="w-full bg-slate-800 border border-slate-700 rounded-lg p-2 text-white"
                 value={mainId} 
                 onChange={e => setMainId(Number(e.target.value))}
               >
                 {pageConfig.角色資料.map((r: Role) => <option key={r.id} value={r.id}>{r.名稱}</option>)}
               </select>
            </div>
          </aside>
        </div>

        <div className="透視容器">
          <section className="黑框舞台" ref={containerRef}>
            <div className="舞台">
              <div className="第四空間" />
              <div className="第三空間" />

              <div className="第二空間">
                {sortedRoles.slice(1).map((r: Role, i: number) => (
                  <div 
                    key={r.id} 
                    className={`角色 ${getThemeClass(r.主題)} ${positionClasses[i + 1]} 已出現`} 
                    data-id={r.id}
                  >
                    <div className="地面影子" />
                    <div className="角色本體">
                      <div className="臉">
                        <div className="眼睛" />
                        <div className="眼睛" />
                      </div>
                      <div className="嘴巴" />
                    </div>
                    <div className="角色標籤">
                      <strong>{r.id}｜{r.名稱}</strong>
                      <span>{r.說明}</span>
                    </div>
                  </div>
                ))}
              </div>

              <div className="第一空間 shadow-2xl">
                {sortedRoles.slice(0, 1).map((r: Role) => (
                  <div 
                    key={r.id} 
                    className={`角色 ${getThemeClass(r.主題)} ${positionClasses[0]} 主角 已出現`} 
                    data-id={r.id}
                  >
                    <div className="主角光環" />
                    <div className="地面影子" />
                    <div className="角色本體">
                      <div className="臉">
                        <div className="眼睛" />
                        <div className="眼睛" />
                      </div>
                      <div className="嘴巴" />
                    </div>
                    <div className="角色標籤">
                      <strong>{r.id}｜{r.名稱}</strong>
                      <span>{r.說明}</span>
                    </div>
                    {/* 紅包僅主角開啟 */}
                    <div className="紅包區">
                      <button 
                        className={`紅包按鈕 ${isErupting ? '已打開' : ''}`} 
                        id="紅包按鈕" 
                        onClick={activateEruption}
                      >
                        <span className="封印章"></span>
                        <span className="提示字">點一下，啟動給予模式</span>
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="特效層" ref={effectLayerRef} />
              <div className="金流層" ref={flowLayerRef} />

              <div className="資訊面板">
                <div className="資訊卡">
                  <h3>空間邏輯</h3>
                  <p>
                    第四空間負責外圍氛圍，第三空間負責深景舞台，第二空間固定放配角，第一空間固定放主角與金流互動。
                  </p>
                </div>
                <div className="資訊卡">
                  <h3>固定色盤</h3>
                  <div className="色盤格">
                    <div className="色塊項"><div className="色塊" style={{background: 'linear-gradient(90deg, #fff1bf, #f0b000)'}} /><div>黃金火焰</div></div>
                    <div className="色塊項"><div className="色塊" style={{background: 'linear-gradient(90deg, #ffffff, #dce7f5)'}} /><div>白色火焰</div></div>
                    <div className="色塊項"><div className="色塊" style={{background: 'linear-gradient(90deg, #87ffc8, #169a5d)'}} /><div>帝王綠</div></div>
                    <div className="色塊項"><div className="色塊" style={{background: 'linear-gradient(90deg, #6957ff, #1c1d2b)'}} /><div>黑鑽能量</div></div>
                    <div className="色塊項"><div className="色塊" style={{background: 'linear-gradient(90deg, #ff7b86, #b20c1b)'}} /><div>血紅能量</div></div>
                  </div>
                </div>
              </div>
            </div>
          </section>
        </div>
      </div>
    </>
  );
}

import React, { useState, useEffect } from 'react';
import { History, Search, Calendar, User, Filter, RefreshCw } from 'lucide-react';
import { EMPEROR_UI, EMPEROR, MU, HUO, SHUI, TU, JIN } from '../constants/wuxingColors';

interface HistoryRecord {
  id: number;
  date: string;
  platform: string;
  employees: number;
  revenue: number;
  status: string;
  auditAt: string;
  reportMode?: string;
}

const STATUS_STYLE: Record<string, { bg: string; color: string; border: string }> = {
  '通過': { bg: MU.abyss, color: MU.bright, border: MU.shadow },
  '警告': { bg: TU.abyss, color: TU.bright, border: TU.shadow },
  '失敗': { bg: HUO.abyss, color: HUO.bright, border: HUO.shadow },
};

const INPUT_STYLE: React.CSSProperties = {
  width: '100%', padding: '6px 10px', borderRadius: 8,
  border: `1px solid ${EMPEROR_UI.borderMain}`, background: EMPEROR.obsidianMid,
  color: EMPEROR_UI.textPrimary, fontSize: 12, outline: 'none',
};

export const HistoryPage: React.FC = () => {
  const [records, setRecords] = useState<HistoryRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [dateFilter, setDateFilter] = useState('');
  const [platformFilter, setPlatformFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [nameFilter, setNameFilter] = useState('');

  const fetchHistory = async () => {
    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams();
      if (dateFilter) params.set('date', dateFilter);
      if (platformFilter) params.set('platform_name', platformFilter);
      const res = await fetch(`/api/v1/history/reports?${params}`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const json = await res.json();
      const list = json.data ?? json.reports ?? json ?? [];
      const mapped: HistoryRecord[] = (Array.isArray(list) ? list : []).map((r: any) => ({
        id: r.id ?? 0,
        date: r.report_date ?? r.reportDate ?? r.date ?? '',
        platform: r.platform_name ?? r.platformName ?? r.platform ?? '',
        employees: r.employee_count ?? r.employeeCount ?? r.employees ?? 0,
        revenue: r.total_revenue ?? r.totalRevenue ?? r.revenue ?? 0,
        status: r.audit_result ?? r.auditResult ?? r.status ?? '—',
        auditAt: r.updated_at ?? r.updatedAt ?? r.auditAt ?? '',
        reportMode: r.report_mode ?? r.reportMode ?? '',
      }));
      setRecords(mapped);
    } catch (e: any) {
      setError(e.message || '無法連線');
      setRecords([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchHistory(); }, [dateFilter, platformFilter]);

  // Client-side filters (status + name)
  const filtered = records.filter(h => {
    if (statusFilter && h.status !== statusFilter) return false;
    if (nameFilter && !h.platform.includes(nameFilter) && !h.date.includes(nameFilter)) return false;
    return true;
  });

  return (
    <div style={{ maxWidth: 1100, margin: '0 auto', padding: '20px 24px', display: 'flex', flexDirection: 'column', gap: 16 }}>
      {/* Header */}
      <div style={{ paddingBottom: 12, borderBottom: `1px solid ${EMPEROR_UI.borderAccent}` }}>
        <h1 style={{ fontSize: 20, fontWeight: 900, color: SHUI.bright, margin: 0, display: 'flex', alignItems: 'center', gap: 10, letterSpacing: '.04em', textShadow: `0 0 12px ${SHUI.bright}44` }}>
          <History size={22} /> 歷史資料查詢
        </h1>
        <p style={{ fontSize: 11, color: EMPEROR_UI.textDim, marginTop: 4 }}>查看過去各日、各平台的業績與審計紀錄（即時 API 資料）</p>
      </div>

      {/* Filters */}
      <div style={{ background: EMPEROR.obsidian, border: `1px solid ${EMPEROR_UI.borderMain}`, borderRadius: 12, padding: '14px 18px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 10, fontSize: 12, fontWeight: 700, color: EMPEROR_UI.textMuted }}>
          <Filter size={14} /> 篩選條件
          <button onClick={fetchHistory} disabled={loading} style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 4, padding: '4px 10px', borderRadius: 6, border: `1px solid ${SHUI.shadow}`, background: 'transparent', color: SHUI.bright, fontSize: 11, fontWeight: 700, cursor: 'pointer' }}>
            <RefreshCw size={12} style={{ animation: loading ? 'spin 1s linear infinite' : 'none' }} /> 重新查詢
          </button>
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 12 }}>
          <div>
            <label style={{ fontSize: 10, color: EMPEROR_UI.textDim, display: 'flex', alignItems: 'center', gap: 4, marginBottom: 4 }}><Calendar size={10} /> 日期</label>
            <input type="date" value={dateFilter} onChange={e => setDateFilter(e.target.value)} style={INPUT_STYLE} />
          </div>
          <div>
            <label style={{ fontSize: 10, color: EMPEROR_UI.textDim, display: 'block', marginBottom: 4 }}>平台</label>
            <select value={platformFilter} onChange={e => setPlatformFilter(e.target.value)} style={INPUT_STYLE}>
              <option value="">全部</option>
              <option>奕心</option>
              <option>民視</option>
              <option>公司產品</option>
            </select>
          </div>
          <div>
            <label style={{ fontSize: 10, color: EMPEROR_UI.textDim, display: 'block', marginBottom: 4 }}>審計狀態</label>
            <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} style={INPUT_STYLE}>
              <option value="">全部</option>
              <option value="通過">通過</option>
              <option value="警告">警告</option>
              <option value="失敗">失敗</option>
            </select>
          </div>
          <div>
            <label style={{ fontSize: 10, color: EMPEROR_UI.textDim, display: 'flex', alignItems: 'center', gap: 4, marginBottom: 4 }}><User size={10} /> 關鍵字搜尋</label>
            <input type="text" value={nameFilter} onChange={e => setNameFilter(e.target.value)} placeholder="搜尋平台/日期..." style={INPUT_STYLE} />
          </div>
        </div>
      </div>

      {/* Error display */}
      {error && (
        <div style={{ padding: '10px 14px', borderRadius: 10, background: HUO.abyss, border: `1px solid ${HUO.shadow}`, color: HUO.bright, fontSize: 12, fontWeight: 700 }}>
          ⚠️ 查詢失敗：{error}（後端可能未啟動，請確認 server 在運行中）
        </div>
      )}

      {/* Results Table */}
      <div style={{ background: EMPEROR.obsidian, border: `1px solid ${EMPEROR_UI.borderMain}`, borderRadius: 12, overflow: 'hidden' }}>
        <div style={{ padding: '10px 18px', borderBottom: `1px solid ${EMPEROR_UI.borderAccent}`, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2 style={{ fontSize: 13, fontWeight: 800, color: EMPEROR_UI.textPrimary, margin: 0, display: 'flex', alignItems: 'center', gap: 8 }}>
            <Search size={14} color={SHUI.bright} /> 查詢結果
          </h2>
          <span style={{ fontSize: 10, color: EMPEROR_UI.textDim }}>{loading ? '載入中...' : `${filtered.length} 筆紀錄`}</span>
        </div>
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12, minWidth: 600 }}>
            <thead>
              <tr style={{ borderBottom: `1px solid ${EMPEROR_UI.borderMain}` }}>
                {['日期', '平台', '模式', '人數', '總業績', '審計', '時間'].map((h, i) => (
                  <th key={h} style={{ padding: '8px 14px', textAlign: i >= 3 && i <= 4 ? 'right' : i === 5 ? 'center' : 'left', fontSize: 10, fontWeight: 700, color: EMPEROR_UI.textDim, letterSpacing: '.06em' }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filtered.map((h, i) => {
                const ss = STATUS_STYLE[h.status] ?? { bg: EMPEROR.obsidianMid, color: EMPEROR_UI.textDim, border: EMPEROR_UI.borderMain };
                return (
                  <tr key={h.id || i} style={{ borderBottom: `1px solid ${EMPEROR_UI.borderMain}18`, transition: 'background .15s', cursor: 'pointer' }}
                    onMouseEnter={e => (e.currentTarget.style.background = 'rgba(255,255,255,0.02)')}
                    onMouseLeave={e => (e.currentTarget.style.background = 'transparent')}>
                    <td style={{ padding: '10px 14px', fontWeight: 700, color: EMPEROR_UI.textPrimary }}>{h.date}</td>
                    <td style={{ padding: '10px 14px', color: SHUI.bright }}>{h.platform}</td>
                    <td style={{ padding: '10px 14px', color: EMPEROR_UI.textMuted, fontSize: 10 }}>{h.reportMode || '—'}</td>
                    <td style={{ padding: '10px 14px', textAlign: 'right', color: EMPEROR_UI.textSecondary }}>{h.employees || '—'}</td>
                    <td style={{ padding: '10px 14px', textAlign: 'right', fontWeight: 800, color: JIN.bright }}>{h.revenue ? `$${h.revenue.toLocaleString()}` : '—'}</td>
                    <td style={{ padding: '10px 14px', textAlign: 'center' }}>
                      <span style={{ fontSize: 10, fontWeight: 700, padding: '2px 8px', borderRadius: 4, background: ss.bg, color: ss.color, border: `1px solid ${ss.border}` }}>{h.status}</span>
                    </td>
                    <td style={{ padding: '10px 14px', color: EMPEROR_UI.textDim, fontSize: 10 }}>{h.auditAt ? new Date(h.auditAt).toLocaleString('zh-TW') : '—'}</td>
                  </tr>
                );
              })}
              {!loading && filtered.length === 0 && (
                <tr><td colSpan={7} style={{ textAlign: 'center', padding: '40px 0', color: EMPEROR_UI.textDim }}>
                  {error ? '查詢失敗' : records.length === 0 ? '尚無歷史紀錄（請先從一鍵流水線處理報表）' : '沒有符合篩選條件的紀錄'}
                </td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <style>{`@keyframes spin { from { transform: rotate(0deg) } to { transform: rotate(360deg) } }`}</style>
    </div>
  );
};

