                   <button onClick={() => copyText(announcement.shortText, 'short')} style={{ flex: 1, minWidth: 140, background: 'rgba(139, 92, 246, 0.1)', border: '1px solid #8b5cf644', color: '#8b5cf6', padding: '14px', borderRadius: 10, fontSize: 13, fontWeight: 900, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8 }}>
                     <Zap size={16} /> 簡潔短版 {copiedKey === 'short' && '✅'}
                   </button>
                   <button onClick={() => copyText(announcement.voiceText, 'voice')} style={{ flex: 1, minWidth: 140, background: 'rgba(59, 130, 246, 0.1)', border: '1px solid #3b82f644', color: '#3b82f6', padding: '14px', borderRadius: 10, fontSize: 13, fontWeight: 900, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8 }}>
                     <Globe size={16} /> 語音播報 {copiedKey === 'voice' && '✅'}
                   </button>
                   <button onClick={() => copyText(announcement.managerText, 'manager')} style={{ flex: 1, minWidth: 140, background: 'rgba(239, 68, 68, 0.08)', border: '1px solid #ef444433', color: '#fca5a5', padding: '14px', borderRadius: 10, fontSize: 13, fontWeight: 900, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8 }}>
                     <ShieldCheck size={16} /> 主管報告 {copiedKey === 'manager' && '✅'}
                   </button>
                </div>
              </div>
            </div>
          )}

        </div>

        {/* 右側：處理進度與 Log 儀表板 — 戰術規格 */}
        <div style={{ 
          background: 'rgba(10, 10, 10, 0.85)', 
          backdropFilter: 'blur(16px)', 
          border: `1px solid ${TU.shadow}`, 
          borderRadius: 24, 
          padding: '28px', 
          color: '#fff', 
          boxShadow: `0 20px 60px rgba(0,0,0,0.6), inset 0 0 0 1px ${TU.void}`, 
          position: 'sticky', 
          top: 24, 
          display: 'flex', 
          flexDirection: 'column', 
          height: 'calc(100vh - 100px)',
          gap: 20
        }}>

           <h3 style={{ margin: 0, fontSize: 16, fontWeight: 900, color: TU.bright, display: 'flex', alignItems: 'center', gap: 12, letterSpacing: '0.1em', textTransform: 'uppercase' }}>
             <Activity size={20} />
             核心分析引擎監測器
           </h3>

           {/* 即時動態數據指標 */}
           <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 10, background: 'rgba(0,0,0,0.4)', padding: 12, borderRadius: 12, border: `1px solid ${TU.void}` }}>
              {[
                { label: 'UPTIME', val: metrics.cpu, clr: TU.bright },
                { label: 'MEMORY', val: metrics.ram, clr: MU.bright },
                { label: 'REPORTS', val: metrics.latency, clr: JIN.bright }
              ].map(m => (
                <div key={m.label} style={{ textAlign: 'center' }}>
                  <div style={{ fontSize: 9, color: TU.shadow, fontWeight: 900 }}>{m.label}</div>
                  <div style={{ fontSize: 13, color: m.clr, fontWeight: 900, fontFamily: 'monospace' }}>{m.val}</div>
                </div>
              ))}
           </div>

           {/* 進度燈號 — 精品版本 */}
           <div style={{ display: 'flex', flexDirection: 'column', gap: 4, position: 'relative' }}>
             {/* 垂直數據軌道 */}
             <div style={{ position: 'absolute', left: 19, top: 20, bottom: 20, width: 2, background: `linear-gradient(to bottom, ${TU.void}, ${TU.shadow}, ${TU.void})`, zIndex: 0 }}></div>

             {stepItems.map((item, idx) => {
               const st = getStepStatus(item.id, step);
               let accent: string = TU.bright;
               let bgColor = 'rgba(20, 20, 20, 0.6)';
               let textColor = '#555';
               let iconColor = '#444';

               if (st === 'done') {
                 accent = MU.bright;
                 bgColor = `${MU.void}`;
                 textColor = '#fff';
                 iconColor = MU.bright;
               } else if (st === 'active') {
                 accent = TU.bright;
                 bgColor = `${TU.void}`;
                 textColor = TU.bright;
                 iconColor = TU.bright;
               } else if (st === 'error') {
                 accent = '#ef4444';
                 bgColor = 'rgba(40, 10, 10, 0.6)';
                 textColor = '#ef4444';
                 iconColor = '#ef4444';
               }

               return (
                 <div key={item.id} style={{ display: 'flex', alignItems: 'center', gap: 18, padding: '14px 0', zIndex: 1, position: 'relative', transition: 'all 0.4s' }}>
                   <div style={{ 
                     width: 40, height: 40, borderRadius: 12, 
                     background: bgColor, 
                     border: `1px solid ${accent}44`, 
                     display: 'flex', alignItems: 'center', justifyContent: 'center', 
                     transition: 'all 0.4s', 
                     boxShadow: st === 'active' ? `0 0 20px ${accent}33` : 'none',
                     color: iconColor
                   }}>
                     {st === 'done' ? <Check size={18} /> : item.icon}
                   </div>
                   <div style={{ 
                     fontSize: 14, 
                     fontWeight: st === 'active' ? 900 : 700, 
                     color: textColor, 
                     transition: 'all 0.4s',
                     letterSpacing: '0.02em',
                     textShadow: st === 'active' ? `0 0 10px ${accent}44` : 'none'
                   }}>
                     {item.label}
                   </div>
                   {st === 'active' && (
                     <div style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 6 }}>
                        <div className="scanning-dot" style={{ width: 6, height: 6, borderRadius: '50%', background: accent, boxShadow: `0 0 10px ${accent}` }}></div>
                        <span style={{ fontSize: 10, color: accent, fontWeight: 900, textTransform: 'uppercase' }}>PROCCESSING</span>
                     </div>
                   )}
                 </div>
               );
             })}
           </div>

           {/* 系統終端日誌區 */}
           <div style={{ 
             flex: 1, 
             background: 'rgba(0,0,0,0.4)', 
             borderRadius: 16, 
             border: `1px solid ${EMPEROR_UI.borderAccent}`, 
             padding: '20px', 
             overflowY: 'auto', 
             display: 'flex', 
             flexDirection: 'column', 
             gap: 10, 
             fontFamily: '"JetBrains Mono", "Fira Code", monospace', 
             fontSize: 12,
             boxShadow: 'inset 0 4px 12px rgba(0,0,0,0.5)'
           }}>
             <div style={{ color: TU.shadow, fontSize: 10, borderBottom: `1px solid ${TU.void}`, paddingBottom: 8, marginBottom: 8, display: 'flex', alignItems: 'center', gap: 6 }}>
               <Layout size={12} /> SYSTEM_KERNEL_LOG v5.01
             </div>
             {logs.length === 0 && <div style={{ color: '#444', fontStyle: 'italic', textAlign: 'center', marginTop: 20 }}>[ 等待遙測連結... ]</div>}
             {logs.map((log) => {
               let clr = '#888';
               if (log.type === 'success') clr = '#10b981';
               if (log.type === 'error') clr = '#ef4444';
               if (log.type === 'warn') clr = '#f59e0b';

               return (
                 <div key={log.id} style={{ display: 'flex', gap: 10, lineHeight: 1.5 }}>
                   <span style={{ color: '#555', flexShrink: 0 }}>[{log.time}]</span>
                   <span style={{ color: clr, wordBreak: 'break-all' }}>{log.msg}</span>
                 </div>
               );
             })}
             <div ref={logsEndRef} />
           </div>

        </div>
      </div>

      <style>{`
        @keyframes pulse {
          0% { opacity: 0.5; transform: scale(1); }
          50% { opacity: 1; transform: scale(1.05); }
          100% { opacity: 0.5; transform: scale(1); }
        }
        @keyframes bgMove {
          0% { transform: scale(1) translate(0, 0); }
          100% { transform: scale(1.1) translate(-2%, -2%); }
        }
        .engine-pulse {
          animation: pulse 2s infinite ease-in-out;
        }
        .scanning-dot {
          animation: pulse 0.8s infinite;
        }
        textarea::placeholder {
          color: ${TU.shadow};
          font-style: italic;
        }
        ::-webkit-scrollbar {
          width: 6px;
        }
        ::-webkit-scrollbar-track {
          background: rgba(0,0,0,0.2);
        }
        ::-webkit-scrollbar-thumb {
          background: ${TU.void};
          border-radius: 10px;
        }
        ::-webkit-scrollbar-thumb:hover {
          background: ${TU.shadow};
        }
      `}</style>
      </div>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { reportService } from '../services/report.service';
import type {
  DailyReportDetail,
  DailyReportTotals,
} from '../types/report';
import { PageBlock } from '../components/PageBlock';
import { StatusBadge } from '../components/StatusBadge';
import { formatMoney, formatPercent } from '../utils/formatters';

interface ParseResultConfirmPageProps {
  reportId: number;
  onAudit?: (reportId: number) => void;
}

const inputStyle: React.CSSProperties = {
  width: '100%',
  border: '1px solid #cbd5e1',
  borderRadius: 6,
  padding: '8px 10px',
  fontSize: 14,
  boxSizing: 'border-box',
  outline: 'none',
  transition: 'border-color 0.2s',
  color: '#334155',
};

const labelStyle: React.CSSProperties = {
  display: 'flex',
  flexDirection: 'column',
  gap: 6,
  fontSize: 13,
  fontWeight: 600,
  color: '#475569',
};

const tableCellStyle: React.CSSProperties = {
  borderBottom: '1px solid #e2e8f0',
  padding: '12px 10px',
  fontSize: 14,
  verticalAlign: 'middle',
  color: '#334155',
};

const buttonStyle: React.CSSProperties = {
  border: 'none',
  borderRadius: 8,
  padding: '10px 16px',
  fontWeight: 600,
  fontSize: 14,
  cursor: 'pointer',
  transition: 'all 0.2s',
};

export function ParseResultConfirmPage({
  reportId,
  onAudit,
}: ParseResultConfirmPageProps): React.ReactElement {
  const [totals, setTotals] = useState<DailyReportTotals | null>(null);
  const [details, setDetails] = useState<DailyReportDetail[]>([]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [saveMessage, setSaveMessage] = useState('');

  async function loadData() {
    try {
      setLoading(true);
      const result = await reportService.getParseResult(reportId);
      setTotals(result.totals as DailyReportTotals);
      setDetails(result.details as DailyReportDetail[]);
      setMessage('');
    } catch (error: any) {
      setMessage(error?.responseMessage || error?.message || '讀取解析結果失敗');
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    void loadData();
  }, [reportId]);

  async function handleSaveTotals() {
    if (!totals) return;

    try {
      setLoading(true);
      await reportService.updateTotals(reportId, {
        totalCalls: totals.totalCalls,
        assignedDealsCount: totals.assignedDealsCount,
        followupDealsCount: totals.followupDealsCount,
        closingRatePercent: totals.closingRatePercent,
        followupAmount: totals.followupAmount,
        cancelledReturnAmount: totals.cancelledReturnAmount,
        totalRevenueAmount: totals.totalRevenueAmount,
        changeReason: '前端解析確認頁人工修正總計',
      });
      setSaveMessage('總計儲存成功 ✅');
      setTimeout(() => setSaveMessage(''), 3000);
    } catch (error: any) {
      setSaveMessage(error?.responseMessage || error?.message || '總計儲存失敗 ❌');
    } finally {
      setLoading(false);
    }
  }

  async function handleSaveDetail(detail: DailyReportDetail) {
    try {
      setLoading(true);
      await reportService.updateDetail(detail.id, {
        employeeName: detail.employeeName,
        normalizedName: detail.normalizedName,
        identityTag: detail.identityTag,
        totalCalls: detail.totalCalls,
        assignedDealsCount: detail.assignedDealsCount,
        followupDealsCount: detail.followupDealsCount,
        closingRatePercent: detail.closingRatePercent,
        followupAmount: detail.followupAmount,
        cancelledReturnAmount: detail.cancelledReturnAmount,
        totalRevenueAmount: detail.totalRevenueAmount,
        changeReason: '前端解析確認頁人工修正明細',
      });
      setSaveMessage(`已儲存：${detail.employeeName} ✅`);
      setTimeout(() => setSaveMessage(''), 3000);
    } catch (error: any) {
      setSaveMessage(error?.responseMessage || error?.message || '明細儲存失敗 ❌');
    } finally {
      setLoading(false);
    }
  }

  function updateTotalsField<K extends keyof DailyReportTotals>(
    key: K,
    value: DailyReportTotals[K]
  ) {
    setTotals((prev) => (prev ? { ...prev, [key]: value } : prev));
  }

  function updateDetailField<K extends keyof DailyReportDetail>(
    rowId: number,
    key: K,
    value: DailyReportDetail[K]
  ) {
    setDetails((prev) =>
      prev.map((item) => (item.id === rowId ? { ...item, [key]: value } : item))
    );
  }

  return (
    <div style={{ background: '#f8fafc', minHeight: '100%', padding: 24 }}>
      <PageBlock
        title="解析結果確認與除錯"
        rightSlot={
          loading ? (
            <StatusBadge label="資料傳輸中..." tone="warn" />
          ) : (
            <StatusBadge label={`目前處理報表編號：${reportId}`} tone="info" />
          )
        }
      >
        {message && (
          <div
            style={{
              padding: 12,
              marginBottom: 16,
              background: '#fef2f2',
              color: '#b91c1c',
              borderRadius: 8,
              fontWeight: 600,
            }}
          >
            {message}
          </div>
        )}

        {totals && (
          <div style={{ marginBottom: 32 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
              <h3 style={{ margin: 0, color: '#1e293b', fontSize: 18 }}>🎯 總計覆核</h3>
              {saveMessage && (
                <span style={{ color: saveMessage.includes('成功') ? '#059669' : '#dc2626', fontWeight: 600, fontSize: 13 }}>
                  {saveMessage}
                </span>
              )}
            </div>

            <div
              style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))',
                gap: 16,
                background: '#ffffff',
                padding: 20,
                borderRadius: 12,
                border: '1px solid #e2e8f0',
                marginBottom: 20,
              }}
            >
              <label style={labelStyle}>
                累積總通數
                <input
                  style={inputStyle}
                  type="number"
                  value={totals.totalCalls}
                  onChange={(e) =>
                    updateTotalsField('totalCalls', Number(e.target.value))
                  }
                />
              </label>

              <label style={labelStyle}>
                派單成交
                <input
                  style={inputStyle}
                  type="number"
                  value={totals.assignedDealsCount}
                  onChange={(e) =>
                    updateTotalsField('assignedDealsCount', Number(e.target.value))
                  }
                />
              </label>

              <label style={labelStyle}>
                追續成交
                <input
                  style={inputStyle}
