      </div>

      {/* ── A 級自動修正紀錄 ── */}
      {aFixes.length > 0 && (
        <div className="wx-card overflow-hidden">
          <div className="wx-card-header flex items-center justify-between">
            <h3 className="font-semibold flex items-center gap-2" style={{ color: 'var(--color-wood-700)' }}>
