        improvement: `(模擬) 增加高客單價開口次數。`,
        course: `(模擬) 系統進階高價實戰班`,
        script: `(模擬) 請問您對於我們最新的升級方案有興趣嗎？`
      }));
    }

    try {
      const model = genAI.getGenerativeModel({ model: MODEL_NAME });

      const prompt = `
你是一位「兆櫃AI派單系統」的頂級 AI 督導總監，同時熟悉高單價追單、續單與銷售心理學。
